    "“Você devia ter me contado antes.”": { en: "“You should have told me sooner.”", es: "«Deberías habérmelo contado antes»", fr: "« Tu aurais dû me le dire plus tôt. »", it: "«Avresti dovuto dirmelo prima.»" },
    "“Eu não esperava que fosse você.”": { en: "“I wasn't expecting you.”", es: "«No esperaba que fueras tú»", fr: "« Je ne m'attendais pas à ce que ce soit toi. »", it: "«Non mi aspettavo che fossi tu.»" },
    "“Isso não era para estar acontecendo.”": { en: "“This wasn't supposed to happen.”", es: "«Se suponía que esto no debía pasar»", fr: "« Ça n'aurait pas dû arriver. »", it: "«Non sarebbe dovuto succedere.»" },
    "“Pode fingir que não me conhece, por favor?”": { en: "“Could you pretend you don't know me, please?”", es: "«¿Puedes fingir que no me conoces, por favor?»", fr: "« Tu peux faire semblant de ne pas me connaître, s'il te plaît ? »", it: "«Puoi fingere di non conoscermi, per favore?»" },
    "“Eu me lembro de tudo, só não do seu nome.”": { en: "“I remember everything, just not your name.”", es: "«Lo recuerdo todo, menos tu nombre»", fr: "« Je me souviens de tout, sauf de ton nom. »", it: "«Ricordo tutto, tranne il tuo nome.»" },
    "“Você é a última pessoa que eu queria ver hoje.”": { en: "“You're the last person I wanted to see today.”", es: "«Eres la última persona que quería ver hoy»", fr: "« Tu es la dernière personne que je voulais voir aujourd'hui. »", it: "«Sei l'ultima persona che volevo vedere oggi.»" },
    "“Prometo que é a última vez que peço isso.”": { en: "“I promise this is the last time I'll ask.”", es: "«Prometo que esta es la última vez que te lo pido»", fr: "« Je te promets que c'est la dernière fois que je te le demande. »", it: "«Prometto che è l'ultima volta che te lo chiedo.»" },
    "“Se eu te contar, você me odeia.”": { en: "“If I tell you, you'll hate me.”", es: "«Si te lo cuento, me odiarás»", fr: "« Si je te le dis, tu me détesteras. »", it: "«Se te lo dico, mi odierai.»" },
    "“Eu fiz uma coisa e não sei como te explicar.”": { en: "“I did something, and I don't know how to explain it to you.”", es: "«Hice algo y no sé cómo explicártelo»", fr: "« J'ai fait quelque chose et je ne sais pas comment te l'expliquer. »", it: "«Ho fatto una cosa e non so come spiegartela.»" },
    "“Não olha para mim assim.”": { en: "“Don't look at me like that.”", es: "«No me mires así»", fr: "« Ne me regarde pas comme ça. »", it: "«Non guardarmi così.»" },
    "“Eu só precisava de um lugar para ficar por uma noite.”": { en: "“I just needed somewhere to stay for one night.”", es: "«Solo necesitaba un lugar donde pasar la noche»", fr: "« J'avais juste besoin d'un endroit où passer la nuit. »", it: "«Avevo solo bisogno di un posto dove stare per una notte.»" },
    "“Que bom que você ainda guarda isso.”": { en: "“I'm glad you still kept this.”", es: "«Me alegra que todavía lo conserves»", fr: "« Je suis contente que tu l'aies gardé. »", it: "«Mi fa piacere che tu l'abbia conservato.»" },
    "“Eu não sei se você vai gostar de saber.”": { en: "“I'm not sure you'll want to know.”", es: "«No sé si te gustará saberlo»", fr: "« Je ne sais pas si tu aimeras l'apprendre. »", it: "«Non so se ti farà piacere saperlo.»" },
    "“Não foi um acidente.”": { en: "“It wasn't an accident.”", es: "«No fue un accidente»", fr: "« Ce n'était pas un accident. »", it: "«Non è stato un incidente.»" },
    "“Pelo menos desta vez, fique.”": { en: "“At least this time, stay.”", es: "«Al menos esta vez, quédate»", fr: "« Pour une fois, reste. »", it: "«Almeno stavolta, resta.»" },
    "“Deve haver uma explicação.”": { en: "“There must be an explanation.”", es: "«Tiene que haber una explicación»", fr: "« Il doit y avoir une explication. »", it: "«Ci deve essere una spiegazione.»" },
    "“Eu jurei que nunca mais voltaria aqui.”": { en: "“I swore I'd never come back here.”", es: "«Juré que nunca volvería aquí»", fr: "« J'avais juré de ne jamais revenir ici. »", it: "«Avevo giurato che non sarei mai più tornata qui.»" },
