function localizePlotValue(category, value, locale = getLanguage(), field = "title") {
    const language = locale === "pt" ? "pt" : locale;
    if (!value) return value;
    if (category.type === "soulmate-date" && language === "pt") {
        return field === "phrase" ? value.phrase : value.title;
    }
    if (language === "pt") return value;
    if (category.type === "ship" || category.type === "music") return value;
    const part = SORTEADOR_LOCALIZED_PARTS[language];
    if (!part) return value;

    if (["setting", "era", "place"].includes(category.id)) {
        const eras = typeof ERAS !== "undefined" ? ERAS : [];
        const places = typeof PLACES !== "undefined" ? PLACES : [];
        const eraIndex = eras.indexOf(value);
        if (eraIndex >= 0) return part.eras[eraIndex];
        for (let i = 0; i < eras.length; i++) {
            for (let j = 0; j < places.length; j++) {
                if (value === `${eras[i]} ${places[j]}`) return `${part.eras[i]} ${part.places[j]}`;
            }
        }
        const fixedSettings = SORTEADOR_DIRECT_TRANSLATIONS[value];
        return fixedSettings ? fixedSettings[language] : value;
    }

    if (category.id === "profession") {
        const roles = typeof ROLES !== "undefined" ? ROLES : [];
        const fixed = SORTEADOR_DIRECT_TRANSLATIONS[value];
        if (fixed) return fixed[language];
        const pair = value.split(" e ");
        if (pair.length === 2) {
            const indices = pair.map(role => roles.findIndex(item => item.toLowerCase() === role.toLowerCase()));
            if (indices.every(index => index >= 0)) {
                const translated = indices.map(index => part.roles[index]);
                const conjunction = { en: "and", es: "y", fr: "et", it: "e" }[language];
                return translated.join(` ${conjunction} `);
            }
        }
        return value;
    }

    if (category.id === "object") {
        const objects = typeof OBJECTS !== "undefined" ? OBJECTS : [];
        const suffixes = typeof OBJECT_SUFFIX !== "undefined" ? OBJECT_SUFFIX : [];
        for (let i = 0; i < objects.length; i++) {
            for (let j = 0; j < suffixes.length; j++) {
                if (value === objects[i] + suffixes[j]) return part.objects[i] + part.objectSuffixes[j];
            }
        }
    }

    if (category.type === "ship-idea" || category.type === "soulmate-date") {
        const special = Object.entries(SHIP_SPECIALS).find(([, shipData]) =>
            category.type === "ship-idea"
                ? shipData.ideas.includes(value)
                : shipData.dates.some(date => date.title === value.title && date.phrase === value.phrase)
        );
        if (!special) return value;
        const [shipKey, shipData] = special;
        const translations = SORTEADOR_SPECIAL_TRANSLATIONS[shipKey][language];
        if (category.type === "ship-idea") return translations.ideas[shipData.ideas.indexOf(value)] || value;
        const dateIndex = shipData.dates.findIndex(date => date.title === value.title && date.phrase === value.phrase);
        const fieldIndex = field === "phrase" ? 1 : 0;
        return translations.dates[dateIndex] && translations.dates[dateIndex][fieldIndex] || value[field] || value.title;
    }
    const listTranslations = SORTEADOR_LIST_TRANSLATIONS[category.id];
    if (listTranslations && category.items) {
        const index = category.items.indexOf(value);
        if (index >= 0 && listTranslations[language][index]) return listTranslations[language][index];
    }
    return (SORTEADOR_DIRECT_TRANSLATIONS[value] || {})[language] || value;
}
